import {escapeHTML as esc} from './component-markings.mjs';
export function normalizeSpeech(text){return text.replace(/kΩ/g,' kiloohmios ').replace(/MΩ/g,' megaohmios ').replace(/Ω/g,' ohmios ').replace(/[µμ]F/g,' microfaradios ').replace(/nF/g,' nanofaradios ').replace(/mA/g,' miliamperios ').replace(/Vpp/g,' voltios pico a pico ').replace(/\bSMD\b/g,' montaje superficial ').replace(/\bPCB\b/g,' placa de circuito impreso ').replace(/→/g,' hacia ').replace(/≈/g,' aproximadamente ').replace(/×/g,' por ').replace(/τ/g,' tau ').replace(/(?<=\d),(?=\d)/g,' coma ');}
export function mountAudioStudio(storage){
 let settings={rate:1.1,volume:.85,voice:'',speechRate:1},dialog=null,current=null;try{settings={...settings,...JSON.parse(storage.getItem('circuitlab-audio-v19')||'{}')};}catch{}const save=()=>{try{storage.setItem('circuitlab-audio-v19',JSON.stringify(settings));}catch{}};
 const button=document.createElement('button');button.className='audioStudioOpen';button.textContent='Voz y audio';button.onclick=open;document.querySelector('header').append(button);
 const synth=globalThis.speechSynthesis;let utterance=null,activeText='';
 function stop(){synth?.cancel();utterance=null;current=null;}
 function open(){const lesson=document.querySelector('#planDialog[open] .planPanel')||document.querySelector('#studyDialog[open]')||document.querySelector('#atlasArticle:not([hidden])');activeText=globalThis.getSelection?.().toString()?.trim()||[...(lesson?.querySelectorAll('h2,h3,p,li')||[])].filter(e=>!e.closest('[hidden]')).map(e=>e.textContent).join('. ');if(!dialog){dialog=document.createElement('dialog');dialog.className='voiceDialog';document.body.append(dialog);dialog.addEventListener('close',stop);}dialog.innerHTML=`<div class="planDialogHead"><div><span class="studioKicker">ESCUCHA A TU RITMO</span><h2>Voz y audio</h2></div><button id="voiceClose" aria-label="Cerrar audio">×</button></div><p>Elige una voz en castellano del dispositivo para escuchar la teoría o el texto seleccionado. La disponibilidad y la naturalidad dependen del navegador.</p><label>Voz de lectura<select id="voiceChoice"></select></label><label>Ritmo de lectura<select id="voiceRate">${[.85,1,1.1,1.2].map(n=>`<option value="${n}" ${n===settings.speechRate?'selected':''}>${n}×</option>`).join('')}</select></label><div class="voiceActions"><button id="voiceRead" class="academyPrimary">▶ Escuchar texto</button><button id="voicePause">Pausar</button><button id="voiceResume">Continuar</button><button id="voiceStop">Detener</button></div><p id="voiceStatus" role="status">${activeText?'Texto preparado: '+activeText.length+' caracteres.':'Abre una lección o selecciona un texto antes de abrir este panel.'}</p><details><summary>Texto preparado para la lectura</summary><p class="voiceText">${esc(activeText||'No hay texto seleccionado.')}</p></details><hr><p>Los vídeos conservan la narración integrada y sus subtítulos. Bajo cada vídeo puedes ajustar velocidad, volumen y retomar tu último punto. No se reproduce audio automáticamente.</p>`;
 const $=id=>dialog.querySelector('#'+id);const voices=()=>{const options=(synth?.getVoices()||[]).filter(v=>v.lang.toLowerCase().startsWith('es')).sort((a,b)=>Number(b.lang==='es-ES')-Number(a.lang==='es-ES')||Number(a.localService)-Number(b.localService));$('voiceChoice').innerHTML=options.length?options.map(v=>`<option value="${esc(v.voiceURI)}">${esc(v.name)} · ${esc(v.lang)}</option>`).join(''):'<option value="">Voz predeterminada en castellano</option>';if(options.some(v=>v.voiceURI===settings.voice))$('voiceChoice').value=settings.voice;};voices();if(synth)synth.addEventListener('voiceschanged',voices,{once:true});
 $('voiceClose').onclick=()=>dialog.close();$('voiceChoice').onchange=e=>{settings.voice=e.target.value;save();};$('voiceRate').onchange=e=>{settings.speechRate=Number(e.target.value);save();};$('voiceRead').disabled=!synth||!activeText;$('voiceRead').onclick=()=>{stop();document.querySelectorAll('video,audio').forEach(v=>v.pause());settings.voice=$('voiceChoice').value;save();const sentences=normalizeSpeech(activeText).split(/(?<=[.!?])\s+/).filter(Boolean);let index=0;const token={};current=token;function next(){if(current!==token)return;if(index>=sentences.length){$('voiceStatus').textContent='Lectura terminada.';return;}utterance=new SpeechSynthesisUtterance(sentences[index++].trim());utterance.lang='es-ES';utterance.voice=synth.getVoices().find(v=>v.voiceURI===settings.voice)||null;utterance.rate=settings.speechRate;utterance.volume=settings.volume;utterance.onend=next;utterance.onerror=e=>{if(e.error!=='canceled'&&e.error!=='interrupted')$('voiceStatus').textContent='Esta voz no ha podido reproducirse. Prueba otra voz del dispositivo.';};synth.speak(utterance);$('voiceStatus').textContent=`Leyendo fragmento ${index} de ${sentences.length}.`;}next();};$('voicePause').onclick=()=>{synth?.pause();$('voiceStatus').textContent='Lectura pausada.';};$('voiceResume').onclick=()=>{synth?.resume();$('voiceStatus').textContent='Lectura reanudada.';};$('voiceStop').onclick=()=>{stop();$('voiceStatus').textContent='Lectura detenida.';};dialog.showModal();}
 function enhance(player){if(player.dataset.audioStudio)return;player.dataset.audioStudio='true';const source=player.querySelector('source')?.getAttribute('src')||player.getAttribute('src')||'',key='circuitlab-video-'+source.split('?')[0];let position=0;try{position=Number(storage.getItem(key))||0;}catch{}player.playbackRate=settings.rate;player.volume=settings.volume;player.preservesPitch=true;
 const panel=document.createElement('div');panel.className='mediaStudio';panel.innerHTML=`<button data-media="back" aria-label="Retroceder diez segundos">↶ 10 s</button><button data-media="forward" aria-label="Avanzar diez segundos">10 s ↷</button><label>Velocidad<select aria-label="Velocidad de vídeo">${[.75,1,1.1,1.25,1.5].map(n=>`<option value="${n}" ${n===settings.rate?'selected':''}>${n}×</option>`).join('')}</select></label><label>Volumen<input aria-label="Volumen de vídeo" type="range" min="0" max="1" step=".05" value="${settings.volume}"></label><button data-media="resume" ${position<2?'hidden':''}>Retomar ${Math.floor(position)} s</button><span role="status">Audio integrado · tono de voz conservado</span>`;player.after(panel);
 panel.querySelector('[data-media=back]').onclick=()=>player.currentTime=Math.max(0,player.currentTime-10);panel.querySelector('[data-media=forward]').onclick=()=>{if(Number.isFinite(player.duration))player.currentTime=Math.min(player.duration,player.currentTime+10);};panel.querySelector('[data-media=resume]').onclick=()=>{const resume=()=>{if(Number.isFinite(player.duration))player.currentTime=Math.min(position,Math.max(0,player.duration-1));player.play().catch(()=>panel.querySelector('[role=status]').textContent='Pulsa ▶ en el vídeo.');};if(player.readyState)resume();else {player.addEventListener('loadedmetadata',resume,{once:true});player.load();}};
 panel.querySelector('select').onchange=e=>{settings.rate=Number(e.target.value);player.playbackRate=settings.rate;save();};panel.querySelector('input').oninput=e=>{settings.volume=Number(e.target.value);player.volume=settings.volume;player.muted=false;save();};let last=-1;player.addEventListener('timeupdate',()=>{const t=Math.floor(player.currentTime);if(t!==last&&t%3===0){last=t;try{storage.setItem(key,String(t));}catch{}}});player.addEventListener('ended',()=>{try{storage.removeItem(key);}catch{}});player.addEventListener('play',()=>{stop();document.querySelectorAll('video,audio').forEach(v=>{if(v!==player)v.pause();});});player.addEventListener('error',()=>panel.querySelector('[role=status]').textContent='No se pudo cargar este vídeo. Comprueba tu conexión.');
 }
 document.addEventListener('circuitlab:lesson-open',e=>{const modal=document.getElementById(e.detail?.target);if(!modal||modal.querySelector('.lessonReadButton'))return;const b=document.createElement('button');b.className='lessonReadButton';b.textContent='Escuchar explicación · elegir voz';b.onclick=open;(modal.querySelector('.lessonPane')||modal).prepend(b);});
 const observer=new MutationObserver(()=>{document.querySelectorAll('video').forEach(enhance);});observer.observe(document.body,{childList:true,subtree:true});document.querySelectorAll('video').forEach(enhance);document.addEventListener('circuitlab:page',()=>{stop();document.querySelectorAll('video,audio').forEach(v=>v.pause());});document.addEventListener('close',e=>{e.target.querySelectorAll?.('video,audio').forEach(v=>v.pause());},true);return {stop};
}
